 "content": "from collections import deque


def transform(grid):
    """Draw a 3x3, color-1 halo around each 2 embedded in a 3-filled object."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == 3:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                          min(x for y, x in cells), max(x for y, x in cells)))

    active = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2 and
              any(r0 <= r <= r1 and c0 <= c <= c1 for r0, r1, c0, c1 in boxes)]
    out = [row[:] for row in grid]
    for r, c in active:
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if out[y][x] != 2:
                    out[y][x] = 1
    return out
